INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_22_m_22_2_56',
  'What does an EC2 instance system status check primarily monitor?',
  'mcq',
  '["The underlying AWS infrastructure that supports the instance.","The operating system and application running on the instance.","The CPU utilization of the instance.","The network connectivity from within the instance."]'::json,
  '{0}'::int[],
  'Option A (correct) states that system status checks monitor the underlying AWS infrastructure. These checks detect problems with the physical host, such as loss of network connectivity, system power issues, or hardware problems. Option B describes what an instance status check monitors, which focuses on the guest operating system. Options C and D are specific metrics that are part of instance status checks or general monitoring, but not the primary focus of a system status check.',
  NOW(),
  'quiz_domain22_5',
  NOW(),
  6,
  NULL,
  NULL,
  'm_22_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
