INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_22_m_22_2_62',
  'A company wants to automatically trigger a Lambda function whenever a specific event occurs in an Amazon S3 bucket, such as an object being uploaded. Which service can facilitate this event-driven architecture?',
