) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_23_m_23_1_45',
  'A SysOps Administrator needs to configure an EC2 Auto Scaling group to scale based on CPU utilization, aiming to keep it around 60%. Which scaling policy type is most suitable for this goal?',
