INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_27_m_27_1_59',
  'A company wants to analyze their historical AWS costs and usage patterns to identify trends and opportunities for optimization. Which service should they use?',
  'mcq',
  '["AWS Cost Explorer","AWS Budgets","AWS Compute Optimizer","Amazon CloudWatch"]'::json,
  '{0}'::int[],
  'Option A (correct) is AWS Cost Explorer, which provides a comprehensive interface to visualize, understand, and manage your AWS costs and usage over time. It allows for detailed analysis of historical data, filtering by service, region, tags, and more. Option B (AWS Budgets) is for setting alerts on spending thresholds. Option C (AWS Compute Optimizer) provides recommendations for right-sizing resources. Option D (Amazon CloudWatch) is a monitoring service for operational data and does not primarily focus on cost analysis.',
  NOW(),
  'quiz_domain27_5',
  NOW(),
  8,
  NULL,
