INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_27_m_27_1_65',
  'Which S3 storage class is designed for data that is accessed less frequently but requires rapid access when needed, at a lower cost than S3 Standard?',
