  'quiz_domain22_5',
  NOW(),
  1,
  NULL,
  NULL,
  'm_22_1',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_22_m_22_1_55',
  'A SysOps Administrator needs to manage the storage costs of Amazon CloudWatch Logs and ensure compliance for different log types. Which CloudWatch Logs features are essential for this task? (Select TWO.)',
