INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_24_m_24_2_83',
  'Which of the following are benefits of using AWS Systems Manager Session Manager for secure remote access to EC2 instances? (Select TWO.)',
  'multiple',
  '["Eliminates the need for open inbound ports on EC2 instances","Provides a fully audited and logged session activity to CloudWatch Logs and AWS CloudTrail","Requires manual management of SSH keys for each instance","Offers a graphical desktop environment for remote administration","Automates the patching of operating systems on instances"]'::json,
  '{0,1}'::int[],
  'Option A (correct) states that Session Manager eliminates the need for open inbound ports on EC2 instances, enhancing security by removing direct internet exposure. Option B (correct) highlights that Session Manager provides a fully audited and logged session activity, sending logs to Amazon CloudWatch Logs and AWS CloudTrail for compliance and monitoring. Option C (incorrect) is a common misconception; Session Manager removes the need for SSH key management, as it uses IAM roles and policies for authentication. Option D (incorrect) is not a primary feature of Session Manager, which provides a command-line interface. Option E (incorrect) describes a capability of AWS Systems Manager Patch Manager, not Session Manager.',
  NOW(),
  'quiz_domain24_5',
  NOW(),
  1,
  NULL,
  NULL,
  'm_24_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
