INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_25_m_25_2_110',
  'Which types of Customer Master Keys (CMKs) in AWS KMS support automatic key rotation? (Select TWO.)',
  'multiple',
  '["Imported CMKs","AWS managed CMKs","Custom key store CMKs","KMS-generated CMKs (customer managed CMKs)","External key store CMKs"]'::json,
  '{1,3}'::int[],
  'Option B (AWS managed CMKs) automatically rotate every year without any action required from the user. Option D (KMS-generated CMKs, also known as customer managed CMKs) can be configured for automatic annual rotation. Option A (Imported CMKs), Option C (Custom key store CMKs), and Option E (External key store CMKs) do not support automatic key rotation; rotation for these types must be managed manually.',
