) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_24_m_24_1_103',
  'A SysOps team needs to update an existing CloudFormation stack with new resource configurations. Order the following steps to perform a controlled update.',
  'ordering',
  '["Execute the change set to apply the updates.","Generate a new CloudFormation template with the updated configurations.","Create a change set for the existing stack using the new template.","Review the proposed changes in the change set."]'::json,
  '{1,2,3,0}'::int[],
  'Updating a CloudFormation stack starts with defining the desired changes in a new template. Option B (Generate a new CloudFormation template with the updated configurations) is the first step. To ensure a controlled update, a change set is created from this new template against the existing stack, as in Option C (Create a change set for the existing stack using the new template). It is crucial to review these proposed changes before applying them, as in Option D (Review the proposed changes in the change set). Finally, if the changes are acceptable, the change set is executed to update the stack, as in Option A (Execute the change set to apply the updates).',
  NOW(),
  'quiz_domain24_5',
  NOW(),
  5,
  NULL,
  NULL,
  'm_24_1',
  'easy'
) ON CONFLICT (id) DO NOTHING;

