INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_26_m_26_1_96',
  'Order the steps to configure a basic Site-to-Site VPN connection to an Amazon VPC.',
  'ordering',
  '["Create a Customer Gateway, providing the public IP address of your on-premises VPN device.","Create a Virtual Private Gateway (VGW) and attach it to your Amazon VPC.","Create a Site-to-Site VPN connection, linking the Customer Gateway and Virtual Private Gateway.","Configure your on-premises VPN device using the configuration file downloaded from AWS."]'::json,
  '{1,0,2,3}'::int[],
  'To configure a basic Site-to-Site VPN connection, start by creating a Virtual Private Gateway (VGW) and attaching it to your Amazon VPC (Option B), which serves as the AWS side of the VPN connection. Next, create a Customer Gateway (Option A), providing the public IP address of your on-premises VPN device. Then, create the Site-to-Site VPN connection itself, linking the newly created Customer Gateway and Virtual Private Gateway (Option C). The final step is to configure your on-premises VPN device using the configuration file downloaded from AWS (Option D) to establish the tunnel.',
  NOW(),
  'quiz_domain26_5',
  NOW(),
  34,
  NULL,
  NULL,
  'm_26_1',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_26_m_26_1_97',
  'Order the steps to create a private subnet within an Amazon VPC.',
  'ordering',
