INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_26_m_26_1_100',
  'A company needs to provide private access from their VPC to an AWS service endpoint, such as Amazon S3, without traversing the public internet. Order the steps to configure a Gateway VPC endpoint for Amazon S3.',
  'ordering',
  '["Create a Gateway VPC endpoint for Amazon S3 in the desired VPC.","Modify the route tables associated with the subnets where instances need S3 access to include a route to the S3 endpoint.","Ensure the security groups and Network ACLs allow outbound traffic to S3.","Verify that instances in the specified subnets can access Amazon S3 privately."]'::json,
