INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_22_m_22_2_106',
  'Match the service to its primary remediation capability.',
  'matching',
  '{"A":"Systems Manager Automation","B":"EC2 Auto Recovery","C":"Amazon EventBridge"}'::json,
  NULL,
  'AWS Systems Manager Automation allows you to define and execute runbooks for automated operational tasks and remediation, such as restarting services or applying patches. Amazon EC2 Auto Recovery is specifically designed to automatically recover Amazon EC2 instances when system status checks fail, ensuring instance availability. Amazon EventBridge acts as a serverless event bus, routing events from various sources to targets for automated actions and remediation, enabling event-driven architectures.',
